[768] = { en = "Gathering Leather", tier = 1,
  t = "Leer verzamelen",
  d = "Gegroet, jongeling. Je ogen glanzen. Ik zie dat je graag terug wilt naar de vlakten om te jagen. Breng eer aan je clan!$B$BIk werk met de huiden van dieren. Ik maak er kleren en harnassen van voor het volk van Thunder Bluff.$B$BJaag op dieren en breng me hun huiden. Dan maak ik iets voor je.",
  o = "Breng 12 stuks Light Leather naar Veren Tallstrider in Thunder Bluff.",
  p = "Hallo weer. Heb je gejaagd? Heb je huiden voor me?",
